'use strict';
(() => {
const {LESSONS,STAGES,SOURCES}=window.IC_COURSE;
const MODEL=window.IC_MODELS;
const KEY='ic-pathway.progress.en.v1';
const $=(s,root=document)=>root.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=window.IC_PROGRESS.blank;
const CHECKS=['I can explain combinational logic, flip-flops, and nonblocking assignment without the reference.','I have written the counter RTL myself and can explain reset, enable, and wraparound.','I have run the self-checks, covered the key behaviors, and confirmed that an intentionally broken design fails.','I have recompiled and run the same design in a licensed VCS environment, keeping actual logs and waveforms.','I have run DC with an authorized cell library and justified constraints, inspecting unconstrained paths and significant warnings.','I have saved the netlist and area/setup/hold reports, and can explain their units, assumptions, and remaining limits.'];
let progress=blank(),canStore=true,current,toastTimer;
function normalize(raw){return window.IC_PROGRESS.normalize(raw,LESSONS,CHECKS.length);}

try{const raw=localStorage.getItem(KEY);if(raw)progress=normalize(JSON.parse(raw));}catch{canStore=false;}
function state(id=current.id){return progress.lessons[id]||(progress.lessons[id]={draft:'',choice:null,quizPassed:false,completed:false});}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(progress));canStore=true;}catch{canStore=false;}$('.local-note').textContent=canStore?'Progress stays in this browser':'Browser storage is unavailable. Export your progress to keep it.';}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function codePanel(code){return code?`<div class="code-panel"><div class="code-header"><span>${esc(code.name)}</span><button class="copy-button" data-copy>Copy code</button></div><pre><code>${esc(code.text)}</code></pre></div>`:'';}
function renderNav(){
 const done=LESSONS.filter(l=>state(l.id).completed).length;
 $('#overall-count').textContent=`${done} / ${LESSONS.length}`;
 $('#overall-progress').max=LESSONS.length;$('#overall-progress').value=done;
 $('#course-nav').innerHTML=STAGES.map((s,i)=>`<div class="nav-group"><h2 class="nav-group-title"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</h2>${LESSONS.filter(l=>l.stage===i).map(l=>`<a class="lesson-link ${l.id===current.id?'active':''}" href="#${l.id}" ${l.id===current.id?'aria-current="page"':''}><span class="nav-number">${String(LESSONS.indexOf(l)+1).padStart(2,'0')}</span><span>${esc(l.title)}</span>${state(l.id).completed?'<span class="nav-done" aria-label="Lesson recorded as complete">✓</span>':''}</a>`).join('')}</div>`).join('');
 $('#pathbar').innerHTML=STAGES.map((s,i)=>`<button class="stage-button ${i===current.stage?'active':''}" data-stage="${i}" ${i===current.stage?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${esc(s.short)}</button>`).join('');
 $('#pathbar').querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>navigate(LESSONS.find(l=>l.stage===Number(b.dataset.stage)).id));
}
function navigate(id){if(location.hash==='#'+id){renderLesson(id,true);}else location.hash=id;}
function setMenu(open){$('#sidebar').classList.toggle('open',open);$('#sidebar-backdrop').hidden=!open;$('#menu-button').setAttribute('aria-expanded',String(open));$('#menu-button').setAttribute('aria-label',open?'Close course navigation':'Open course navigation');}
function checklist(){return `<section class="exercise-card"><div class="section-label">PRACTICAL ACCEPTANCE · CONFIRM YOUR OWN EVIDENCE</div><h2>Six pieces of practical evidence</h2><div class="checklist">${CHECKS.map((text,i)=>`<label><input type="checkbox" data-accept="${i}" ${progress.acceptance[i]?'checked':''}><span>${esc(text)}</span></label>`).join('')}</div><p id="acceptance-count" class="completion-note"></p></section>`;}
function updateAcceptance(){const n=CHECKS.filter((_,i)=>progress.acceptance[i]).length;const el=$('#acceptance-count');if(el)el.textContent=`You have confirmed ${n} of ${CHECKS.length} items. Leave unperformed practical tasks unchecked.`;}
function completionStatus(){
 const st=state(),el=$('#completion-note');el.classList.toggle('done',st.completed);
 el.textContent=st.completed?'Lesson completion is recorded. Confirm real tool practice separately in the final acceptance checklist.':st.quizPassed&&st.draft.trim()?'The knowledge check passed and your response is saved. You can record this lesson as complete.':'Write a practice response and pass the knowledge check to record completion. If a practical run is pending, say so in your response.';
 const b=$('#complete-lesson');b.textContent=st.completed?'Completed · mark for review':'Record lesson completion';b.disabled=!st.completed&&(!st.quizPassed||!st.draft.trim());
}
function renderLesson(id,focus=false){
 current=LESSONS.find(l=>l.id===id)||LESSONS[0];progress.last=current.id;persist();const st=state(),index=LESSONS.indexOf(current);
 renderNav();setMenu(false);document.title=`${current.title} · IC Pathway`;
 const sourceHtml=(current.sources||[]).map(k=>SOURCES[k]).filter(Boolean).map(([name,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a>`).join('');
 const downloadHtml=current.download?`<aside class="side-note"><h3>Counter reference project</h3><p>Includes RTL, a self-checking testbench, Icarus/VCS scripts, and DC teaching templates. Obtain commercial tools and libraries through your institution.</p><a class="resource-download" href="./downloads/ic-counter-lab.zip" download>Download the complete lab .zip ↓</a><a href="./downloads/README.txt" target="_blank" rel="noopener" class="source-links">Read setup and validation notes first ↗</a></aside>`:'';
 $('#lesson').innerHTML=`<header class="lesson-header"><div class="lesson-topline"><span class="label">${esc(STAGES[current.stage].title)} / ${String(index+1).padStart(2,'0')}</span><span>Lesson ${index+1} of ${LESSONS.length} · About ${current.minutes} min to read</span></div><h1>${esc(current.title)}</h1><p class="lesson-intro">${esc(current.intro)}</p><ul class="objective-list">${current.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></header><div class="lesson-layout"><div class="reading-column">${current.sections.map(([h,p])=>`<section class="reading-block"><h2>${esc(h)}</h2><p>${esc(p)}</p></section>`).join('')}${codePanel(current.code)}<aside class="callout warning"><strong>A common pitfall</strong>${esc(current.trap)}</aside></div><div class="practice-column">${current.lab?'<section id="interactive-lab" class="lab-card" aria-label="Interactive teaching model for this lesson"></section>':''}<aside class="side-note"><h3>How to study this lesson</h3><p>Predict an outcome before trying it. Write down what you do not understand, then compare your reasoning with the reference answer.</p><p>${current.stage<3?'Browser models follow explicit teaching rules. Validate actual HDL code in a simulator.':'Check VCS/DC commands against your installed versions. Record real tool results separately from website knowledge checks.'}</p></aside>${downloadHtml}<aside class="side-note"><h3>Further reading</h3><div class="source-links">${sourceHtml}</div><p style="margin-top:12px">Use these primary references to check details and explore further after working through this lesson.</p></aside></div></div><section class="exercise-card"><div class="section-label">PRACTICE / TRY IT YOURSELF FIRST</div><h2>Write your response</h2><p id="exercise-task">${esc(current.exercise.task)}</p><label for="exercise-answer" class="sr-only">Your response to this lesson's exercise</label><textarea id="exercise-answer" class="exercise-input" maxlength="15000" aria-describedby="exercise-task" placeholder="${esc(current.exercise.placeholder)}"></textarea><div class="button-row"><button id="save-answer" class="secondary-button">Save my response</button><span id="draft-status" class="completion-note" aria-live="polite"></span></div><details class="answer-details"><summary>Show the reference answer and review guidance</summary><p style="white-space:pre-wrap">${esc(current.exercise.answer)}</p></details><p class="completion-note">Review open responses against the reference. Saving text does not compile code or verify its correctness.</p></section><section class="exercise-card"><div class="section-label">KNOWLEDGE CHECK / IMMEDIATE FEEDBACK</div><form id="quiz-form"><fieldset><legend class="quiz-question">${esc(current.quiz.q)}</legend><div class="quiz-options">${current.quiz.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="quiz" value="${i}" ${st.choice===i?'checked':''}><span>${String.fromCharCode(65+i)}. ${esc(o)}</span></label>`).join('')}</div></fieldset><div class="button-row"><button class="primary-button" type="submit">Check answer</button></div><div id="quiz-feedback" class="feedback ${st.quizPassed?'good':''}" role="status">${st.quizPassed?'Correct. '+esc(current.quiz.why):''}</div></form></section>${current.checklist?checklist():''}<div class="lesson-navigation"><button id="prev-lesson" class="secondary-button" ${index===0?'disabled':''}>Previous</button><button id="complete-lesson" class="primary-button">Record lesson completion</button><button id="next-lesson" class="secondary-button" ${index===LESSONS.length-1?'disabled':''}>Next lesson →</button></div><p id="completion-note" class="completion-note"></p>`;
 $('#exercise-answer').value=st.draft;
 $('#exercise-answer').oninput=()=>{st.draft=$('#exercise-answer').value;if(!st.draft.trim()&&st.completed){st.completed=false;renderNav();}persist();$('#draft-status').textContent=canStore?'Saved automatically':'Kept in this session; please export';completionStatus();};
 $('#save-answer').onclick=()=>{st.draft=$('#exercise-answer').value;persist();$('#draft-status').textContent=canStore?'Saved':'Export progress to keep it';toast(canStore?'Response saved in this browser':'Browser storage is unavailable. Please export your progress.');completionStatus();};
 $('#quiz-form').onchange=()=>{st.choice=Number($('#quiz-form input:checked').value);st.quizPassed=false;st.completed=false;persist();renderNav();$('#quiz-feedback').textContent='';completionStatus();};
 $('#quiz-form').onsubmit=e=>{e.preventDefault();const checked=$('#quiz-form input:checked'),feedback=$('#quiz-feedback');if(!checked){feedback.className='feedback';feedback.textContent='Choose an answer before checking.';return;}st.choice=Number(checked.value);st.quizPassed=st.choice===current.quiz.correct;if(!st.quizPassed)st.completed=false;feedback.className='feedback '+(st.quizPassed?'good':'bad');feedback.textContent=(st.quizPassed?'Correct. ':'Take another look. ')+current.quiz.why;persist();renderNav();completionStatus();};
 $('#complete-lesson').onclick=()=>{st.completed=!st.completed;persist();renderNav();completionStatus();toast(st.completed?'Completion recorded. Continue to the next lesson when ready.':'Marked for review');};
 $('#prev-lesson').onclick=()=>index>0&&navigate(LESSONS[index-1].id);
 $('#next-lesson').onclick=()=>index<LESSONS.length-1&&navigate(LESSONS[index+1].id);
 $('[data-copy]')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(current.code.text);toast('Code copied');}catch{const range=document.createRange();range.selectNodeContents($('.code-panel code'));const s=window.getSelection();s.removeAllRanges();s.addRange(range);toast('Code selected. Use the copy command on your device.');}});
 document.querySelectorAll('[data-accept]').forEach(input=>input.onchange=()=>{progress.acceptance[input.dataset.accept]=input.checked;persist();updateAcceptance();});
 updateAcceptance();completionStatus();if(current.lab)renderLab(current.lab);
 if(focus){window.scrollTo({top:0,behavior:'instant'});$('#lesson').focus({preventScroll:true});}
}
function labFrame(title,desc,content,note='Teaching model · Calculated in JavaScript; does not execute Verilog or simulate device delays.'){$('#interactive-lab').innerHTML=`<div class="lab-eyebrow">EXPLORE / INTERACTIVE</div><h2>${esc(title)}</h2><p>${esc(desc)}</p>${content}<p class="lab-note">${esc(note)}</p>`;}
function readout(label,value,id=''){return `<div class="readout"><span>${esc(label)}</span><strong ${id?'id="'+id+'"':''}>${esc(value)}</strong></div>`;}
function wave(values,labels=['count']){
 const n=Math.max(1,values.length),width=Math.max(320,n*42+55),rowH=38;
 let body='';for(let i=0;i<n;i++)body+=`<line class="grid" x1="${50+i*42}" x2="${50+i*42}" y1="0" y2="${labels.length*rowH+30}"/>`;
 labels.forEach((label,r)=>{let y=20+r*rowH;body+=`<text x="0" y="${y+4}">${esc(label)}</text>`;for(let i=0;i<n;i++){const v=Array.isArray(values[i])?values[i][r]:values[i];body+=`<rect x="${53+i*42}" y="${y-12}" width="36" height="24" rx="3" fill="#304c5c"/><text x="${71+i*42}" y="${y+4}" text-anchor="middle">${esc(v)}</text>`;}});
 for(let i=0;i<n;i++)body+=`<text x="${71+i*42}" y="${labels.length*rowH+20}" text-anchor="middle">${i}</text>`;
 return `<svg class="wave-svg" role="img" aria-label="State samples by clock event; read columns from left to right" viewBox="0 0 ${width} ${labels.length*rowH+30}">${body}</svg>`;
}
function renderLab(kind){
 if(kind==='bits'){
  let value=10;labFrame('Four bits, sixteen patterns','Toggle a bit and observe its weight and the unsigned value.',`<div class="bit-grid">${[3,2,1,0].map(i=>`<button class="bit" data-bit="${i}" aria-label="Toggle bit ${i}" aria-pressed="false">0<small>Weight ${2**i}</small></button>`).join('')}</div><div class="readouts">${readout('Unsigned decimal','10','bit-dec')}${readout('Binary','1010','bit-bin')}</div><div id="bit-equation" class="equation"></div><button id="bit-add" class="lab-button">Add 1; keep four bits</button>`);
  const update=()=>{document.querySelectorAll('[data-bit]').forEach(b=>{const i=Number(b.dataset.bit),on=(value>>i)&1;b.setAttribute('aria-pressed',String(!!on));b.innerHTML=`${on}<small>Weight ${2**i}</small>`;});$('#bit-dec').textContent=value;$('#bit-bin').textContent=value.toString(2).padStart(4,'0');$('#bit-equation').textContent=[3,2,1,0].map(i=>`${(value>>i)&1}×${2**i}`).join(' + ')+` = ${value}`;};
  document.querySelectorAll('[data-bit]').forEach(b=>b.onclick=()=>{value^=1<<Number(b.dataset.bit);update();});$('#bit-add').onclick=()=>{value=(value+1)&15;update();};update();
 }else if(kind==='gates'){
  let a=0,b=1,gate='AND';const calc=(x,y)=>gate==='AND'?x&y:gate==='OR'?x|y:x^y;
  labFrame('Explore a truth table','Predict the output, then change the inputs or gate.',`<label for="gate-type">Gate <select id="gate-type" class="lab-select"><option>AND</option><option>OR</option><option>XOR</option></select></label><div class="lab-controls"><button id="gate-a" class="lab-button" aria-pressed="false">A = 0</button><button id="gate-b" class="lab-button" aria-pressed="true">B = 1</button></div><div class="readouts">${readout('Output Y','0','gate-out')}${readout('Expression','A & B','gate-expr')}</div><table class="truth-table"><caption class="sr-only">Truth table for the selected gate</caption><thead><tr><th>A</th><th>B</th><th>Y</th></tr></thead><tbody id="truth-body"></tbody></table>`);
  const update=()=>{$('#gate-a').textContent='A = '+a;$('#gate-a').setAttribute('aria-pressed',String(!!a));$('#gate-b').textContent='B = '+b;$('#gate-b').setAttribute('aria-pressed',String(!!b));$('#gate-out').textContent=calc(a,b);$('#gate-expr').textContent=`A ${{AND:'&',OR:'|',XOR:'^'}[gate]} B`;$('#truth-body').innerHTML=[0,1,2,3].map(n=>{const x=n>>1,y=n&1;return `<tr class="${x===a&&y===b?'highlight':''}"><td>${x}</td><td>${y}</td><td>${calc(x,y)}</td></tr>`;}).join('');};
  $('#gate-a').onclick=()=>{a^=1;update();};$('#gate-b').onclick=()=>{b^=1;update();};$('#gate-type').onchange=e=>{gate=e.target.value;update();};update();
 }else if(kind==='mux'){
  let sel=0;labFrame('A two-input datapath','Edit two four-bit inputs and toggle the selector.',`<div class="lab-controls"><label>A <input id="mux-a" class="lab-input" type="number" min="0" max="15" step="1" value="9"></label><label>B <input id="mux-b" class="lab-input" type="number" min="0" max="15" step="1" value="7"></label></div><button id="mux-select" class="lab-button" aria-pressed="false">sel = 0 · select A</button><div class="readouts">${readout('MUX output Y','9','mux-out')}${readout('Five-bit sum','10000','mux-sum')}</div><p id="mux-equation" class="equation"></p>`);
  const update=()=>{const av=Number($('#mux-a').value),bv=Number($('#mux-b').value);if(!Number.isInteger(av)||!Number.isInteger(bv)||av<0||av>15||bv<0||bv>15||$('#mux-a').value===''||$('#mux-b').value===''){$('#mux-equation').textContent='Enter integers from 0 to 15.';$('#mux-out').textContent='—';$('#mux-sum').textContent='—';return;}$('#mux-out').textContent=sel?bv:av;$('#mux-sum').textContent=(av+bv).toString(2).padStart(5,'0');$('#mux-equation').textContent=`${av} + ${bv} = ${av+bv}`;};
  $('#mux-a').oninput=update;$('#mux-b').oninput=update;$('#mux-select').onclick=()=>{sel^=1;$('#mux-select').textContent=`sel = ${sel} · select ${sel?'B':'A'}`;$('#mux-select').setAttribute('aria-pressed',String(!!sel));update();};update();
 }else if(kind==='clock'||kind==='nba'){
  let d=1,a=0,b=0,history=[[0,0]];const nba=kind==='nba';
  labFrame(nba?'Old values through two registers':'Sample D on an edge',nba?'a <= d; b <= a. Compare the two registers after each edge.':'Changing D does not immediately change Q. Apply a rising edge to sample it.',`<div class="lab-controls"><button id="ff-d" class="lab-button" aria-pressed="true">D = 1</button><button id="ff-edge" class="lab-button primary">Apply a rising edge ↑</button><button id="ff-reset" class="lab-button">Reset and clock once</button></div><div class="readouts">${readout(nba?'Register a':'D input','1','ff-a')}${readout(nba?'Register b':'Stored Q','0','ff-b')}</div><div id="ff-history" class="wave-wrap"></div><p id="ff-caption"></p>`);
  const update=()=>{$('#ff-d').textContent='D = '+d;$('#ff-d').setAttribute('aria-pressed',String(!!d));$('#ff-a').textContent=nba?a:d;$('#ff-b').textContent=nba?b:a;$('#ff-history').innerHTML=wave(history,nba?['a','b']:['D','Q']);};
  $('#ff-d').onclick=()=>{d^=1;update();$('#ff-caption').textContent='The input changed; no new sampling edge has occurred.';};
  $('#ff-edge').onclick=()=>{const old=a;({a,b}=MODEL.pipeline(a,d));history.push(nba?[a,b]:[d,a]);history=history.slice(-7);update();$('#ff-caption').textContent=nba?`a sampled D=${d}; b sampled the earlier a=${old}.`:`Q sampled D=${d} at this edge.`;};
  $('#ff-reset').onclick=()=>{a=0;b=0;history=[nba?[0,0]:[d,0]];update();$('#ff-caption').textContent='Synchronous reset was applied together with an active edge.';};if(!nba)history=[[d,a]];update();
 }else if(kind==='counter'){
  let value=0,en=1,rst=1,cycle=0,history=[[0,1,1]];
  labFrame('Step a four-bit counter','Set reset and enable, then apply clock edges. The initial state has already been reset.',`<div class="lab-controls"><button id="count-en" class="lab-button" aria-pressed="true">en = 1 · count</button><button id="count-rst" class="lab-button" aria-pressed="false">rst_n = 1 · reset inactive</button></div><div id="count-value" class="clock-label">0000</div><div class="lab-controls"><button id="count-step" class="lab-button primary">Next edge ↑</button><button id="count-many" class="lab-button">Advance 16 edges</button><button id="count-restart" class="lab-button">Restart</button></div><div class="readouts">${readout('Decimal count','0','count-dec')}${readout('Edges advanced','0','count-cycle')}</div><div id="count-history" class="wave-wrap"></div><p id="count-caption">The register waits for a clock edge after control signals change.</p>`);
  const update=()=>{$('#count-value').textContent=value.toString(2).padStart(4,'0');$('#count-dec').textContent=value;$('#count-cycle').textContent=cycle;$('#count-en').textContent=`en = ${en} · ${en?'count':'hold'}`;$('#count-en').setAttribute('aria-pressed',String(!!en));$('#count-rst').textContent=`rst_n = ${rst} · ${rst?'reset inactive':'reset active'}`;$('#count-rst').setAttribute('aria-pressed',String(!rst));$('#count-history').innerHTML=wave(history,['Q','en','rst_n']);};
  const step=()=>{value=MODEL.nextCounter(value,en,rst,4);cycle++;history.push([value,en,rst]);history=history.slice(-7);};
  $('#count-en').onclick=()=>{en^=1;update();};$('#count-rst').onclick=()=>{rst^=1;update();$('#count-caption').textContent='Reset changed; synchronous reset takes effect at the next edge.';};
  $('#count-step').onclick=()=>{step();update();$('#count-caption').textContent=!rst?'Reset has priority at this edge, so count becomes zero.':en?'Enable is high: add one and retain the lowest four bits.':'Enable is low: count holds its value.';};
  $('#count-many').onclick=()=>{for(let i=0;i<16;i++)step();update();$('#count-caption').textContent='Advanced 16 edges. The trace retains the seven most recent samples.';};
  $('#count-restart').onclick=()=>{value=0;en=1;rst=1;cycle=0;history=[[0,1,1]];update();$('#count-caption').textContent='Returned to the already-reset starting state.';};update();
 }else if(kind==='fsm'){
  let s='IDLE',start=0,finish=0;const next=()=>MODEL.nextFSM(s,start,finish);
  labFrame('A three-state controller','Inputs affect next_state; the clock edge updates state.',`<div class="lab-controls"><button id="fsm-start" class="lab-button" aria-pressed="false">start = 0</button><button id="fsm-finish" class="lab-button" aria-pressed="false">finish = 0</button></div><div class="readouts">${readout('Current state','IDLE','fsm-state')}${readout('Next state','IDLE','fsm-next')}</div><p id="fsm-output" class="equation"></p><div class="lab-controls"><button id="fsm-edge" class="lab-button primary">Next edge ↑</button><button id="fsm-reset" class="lab-button">Reset and clock once</button></div>`);
  const update=()=>{$('#fsm-start').textContent='start = '+start;$('#fsm-start').setAttribute('aria-pressed',String(!!start));$('#fsm-finish').textContent='finish = '+finish;$('#fsm-finish').setAttribute('aria-pressed',String(!!finish));$('#fsm-state').textContent=s;$('#fsm-next').textContent=next();$('#fsm-output').textContent=`busy = ${s==='RUN'?1:0} · done = ${s==='DONE'?1:0}`;};
  $('#fsm-start').onclick=()=>{start^=1;update();};$('#fsm-finish').onclick=()=>{finish^=1;update();};$('#fsm-edge').onclick=()=>{s=next();update();};$('#fsm-reset').onclick=()=>{s='IDLE';start=0;finish=0;update();};update();
 }else if(kind==='timing'){
  labFrame('How does a shorter period affect slack?','Simplified setup model: arrival time is 7.8 ns; setup time plus uncertainty is 0.7 ns.',`<label for="period-slider">Clock period <span id="period-label">10.0 ns</span></label><input id="period-slider" type="range" min="4" max="16" step="0.1" value="10"><div class="readouts">${readout('Target frequency','100 MHz','timing-freq')}${readout('Setup slack','1.5 ns','timing-slack')}</div><div class="demo-meter" aria-hidden="true"><span id="timing-meter"></span></div><p id="timing-equation" class="equation"></p><p id="timing-state"></p>`,'Illustrative values · Not a DC report or full STA; omits skew, detailed cell arcs, and parasitics.');
  const update=()=>{const p=Number($('#period-slider').value),slack=MODEL.setupSlack(p);$('#period-label').textContent=p.toFixed(1)+' ns';$('#timing-freq').textContent=(1000/p).toFixed(1)+' MHz';$('#timing-slack').textContent=(slack>=0?'+':'')+slack.toFixed(1)+' ns';$('#timing-equation').textContent=`${p.toFixed(1)} − 0.7 − 7.8 = ${slack.toFixed(1)} ns`;$('#timing-state').textContent=slack>=0?'The setup budget is met in this simplified model.':'The setup budget is violated in this simplified model.';$('#timing-meter').style.width=Math.min(100,8.5/p*100)+'%';$('#timing-meter').style.background=slack>=0?'#79caaa':'#ff9a72';};$('#period-slider').oninput=update;update();
 }
}
$('#menu-button').onclick=()=>setMenu(!$('#sidebar').classList.contains('open'));
$('#sidebar-backdrop').onclick=()=>{setMenu(false);$('#menu-button').focus();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){setMenu(false);$('#menu-button').focus();}});
$('#export-progress').onclick=()=>download('ic-pathway-progress.json',JSON.stringify({...progress,exportedAt:new Date().toISOString()},null,2));
$('#import-button').onclick=()=>$('#import-progress').click();
$('#import-progress').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw Error('File too large. Select a progress file exported by this course.');const imported=normalize(JSON.parse(await file.text()));for(const [id,v]of Object.entries(imported.lessons)){const old=progress.lessons[id];if(!old||v.completed||!old.completed)progress.lessons[id]=v;}for(let i=0;i<CHECKS.length;i++)progress.acceptance[i]=!!progress.acceptance[i]||!!imported.acceptance[i];persist();renderLesson(current.id);toast('Progress imported; completed lesson records were retained.');}catch(error){toast('Import failed: '+error.message);}e.target.value='';};
window.addEventListener('hashchange',()=>renderLesson(location.hash.slice(1),true));
renderLesson(location.hash.slice(1)||progress.last);
})();
